uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

out vec4 fragColor;

// --- Helper Functions ---

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Smooth random hash for value noise
vec2 hash22(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}

// Cubic interpolated value noise (Silky smooth, no hard edges)
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Smooth cubic curve
    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix( mix( dot( hash22(i + vec2(0.0,0.0)), f - vec2(0.0,0.0) ), 
                     dot( hash22(i + vec2(1.0,0.0)), f - vec2(1.0,0.0) ), u.x),
                mix( dot( hash22(i + vec2(0.0,1.0)), f - vec2(0.0,1.0) ), 
                     dot( hash22(i + vec2(1.0,1.0)), f - vec2(1.0,1.0) ), u.x), u.y);
}

// Fractional Brownian Motion (Multi-layered noise for organic detail)
float fbm(vec2 x) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    // Rotate to reduce axial bias (looks more natural)
    mat2 r = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for (int i = 0; i < 5; ++i) {
        v += a * noise(x);
        x = r * x * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}

// Visceral / Real-Life Tissue Palette (Blood reds, Mucosal pinks, Subdermal peach)
vec3 palette(float t) {
    vec3 a = vec3(0.65, 0.25, 0.25); // Deep flesh
    vec3 b = vec3(0.35, 0.15, 0.15); // Blood contrast
    vec3 c = vec3(1.0, 1.0, 1.0);    // Full range
    vec3 d = vec3(0.00, 0.10, 0.15); // Slight shift towards purple/blue veins
    return a + b * cos(6.28318 * (c * t + d));
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing (Slowed down slightly for realistic fluid motion)
    float spd = (u_speed <= 0.0) ? 0.15 : u_speed * 0.5;
    float t = iTime * spd;

    // --- Background (Deep Inner Cavity) ---
    vec3 bgTop = vec3(0.15, 0.02, 0.03); // Dark red
    vec3 bgBottom = vec3(0.05, 0.0, 0.01); // Near black blood
    vec3 finalColor = mix(bgBottom, bgTop, uv0.y + 0.5);

    // 3. Layer Loop
    float density = (u_layers <= 0.0) ? 3.0 : u_layers;
    float scale = (u_scale <= 0.0) ? 2.5 : u_scale * 3.0; 
    float brightness = (u_intensity <= 0.0) ? 1.2 : u_intensity;

    for(float i = 0.0; i < 4.0; i++) {
        if(i >= density) break;

        // --- Space Setup ---
        vec2 p = uv0 * scale * (1.0 + i * 0.3);

        // Gentle organic breathing/drifting
        p.y -= t * 0.2 * (i + 1.0);
        p.x += sin(t * 0.3 + i) * 0.2;
        p *= rot(sin(t * 0.05 + i) * 0.1);

        // --- Domain Warping (The "Silk" Math) ---
        // We feed noise into noise to create fluid, folded currents
        vec2 q = vec2(0.0);
        q.x = fbm(p + vec2(0.0, 0.0) + t * 0.1);
        q.y = fbm(p + vec2(5.2, 1.3) - t * 0.15);

        vec2 r = vec2(0.0);
        r.x = fbm(p + 4.0 * q + vec2(1.7, 9.2) + t * 0.2);
        r.y = fbm(p + 4.0 * q + vec2(8.3, 2.8) - t * 0.1);

        // Final folded height map of the tissue
        float tissueHeight = fbm(p + 4.0 * r);

        // --- Lighting & Material (Wet / Fleshy) ---
        // Base color maps to the depth of the folds
        vec3 col = palette(tissueHeight * 2.0 + i * 0.1 + t * u_color_cycle);

        // Subsurface scattering: glowing warmth inside the folds
        float subsurface = smoothstep(0.2, 0.0, abs(tissueHeight - 0.5));
        col += vec3(0.6, 0.1, 0.0) * subsurface * 0.8;

        // Specular highlight: Makes it look "wet" by reflecting fake light off the noise gradient
        float wetHighlight = pow(max(0.0, sin(r.y * 6.0 + t)), 4.0);
        vec3 specColor = vec3(0.9, 0.85, 0.8) * wetHighlight * 0.6;

        // --- Blending ---
        // Calculate how thick this membrane layer is
        float alpha = smoothstep(-0.2, 0.8, tissueHeight);

        // Fade out layers as they get closer to the camera so they don't block everything
        float layerFade = 1.0 - (i / 4.0);
        alpha *= layerFade;

        // Mix the translucent tissue over the background
        finalColor = mix(finalColor, col * brightness + specColor * brightness, alpha);
    }

    // 5. Post-Processing
    // Microscope Vignette
    float vig = 1.0 - length(uv0) * 0.5;
    finalColor *= vig;

    // Cinematic organic tone mapping
    finalColor = smoothstep(0.0, 1.1, finalColor);

    fragColor = vec4(finalColor, 1.0);
}
